-- ============================================================
-- MORE GROUPS: Pre-Engineering ("eng") and Commerce ("commerce") at Grades 11-12
-- for BIEK, AKU-EB, FBISE (+ Cambridge / Edexcel A Level streams).
-- Also corrects BIEK to its own HSC scheme of studies (compulsory subjects,
-- Science General, Commerce and Humanities sets A-E).
--
-- Group codes were limited to bio/comp/arts by CHECK constraints. They are now
-- validated by foreign keys to curriculum_groups (courses, students) and by the
-- API against lib/curriculum.ts (enquiries), so the CHECKs only enforce format.
-- Safe to re-run.
-- ============================================================

ALTER TABLE public.curriculum_groups DROP CONSTRAINT IF EXISTS curriculum_groups_code_check;
ALTER TABLE public.curriculum_groups ADD CONSTRAINT curriculum_groups_code_check
  CHECK (code ~ '^[a-z][a-z_]{1,29}$');

ALTER TABLE public.enquiries DROP CONSTRAINT IF EXISTS enquiries_group_code_check;
ALTER TABLE public.enquiries ADD CONSTRAINT enquiries_group_code_check
  CHECK (group_code ~ '^[a-z][a-z_]{1,29}$');

-- BEGIN CURRICULUM SEED (generated by scripts/generate-curriculum-sql.mjs; do not edit by hand)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, short_name = EXCLUDED.short_name, family = EXCLUDED.family, sort_order = EXCLUDED.sort_order;

ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

ON CONFLICT (board, stage) DO UPDATE SET label = EXCLUDED.label, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;

ON CONFLICT (board, stage, code) DO UPDATE SET name = EXCLUDED.name, electives_required = EXCLUDED.electives_required, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;

DELETE FROM public.curriculum_group_subjects;
SELECT g.board, g.stage, g.group_code, s.code, s.kind,
       (row_number() OVER (PARTITION BY g.board, g.stage, g.group_code ORDER BY s.kind_order, s.ord))::int - 1
FROM (VALUES
  ('bsek', 'secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics', 'sindhi'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('bsek', 'secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics', 'sindhi'], ARRAY['physics', 'chemistry', 'computer_science'], ARRAY[]::text[]),
  ('bsek', 'secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics', 'sindhi'], ARRAY['general_science'], ARRAY['computer_science', 'economics', 'civics', 'education', 'geography', 'islamic_history', 'islamic_studies', 'statistics', 'business_studies', 'english_literature', 'arabic', 'home_economics', 'physiology_hygiene', 'fine_arts', 'health_physical_education']),
