  ('aku_eb', 'secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics'], ARRAY['physics', 'chemistry', 'computer_science'], ARRAY[]::text[]),
  ('aku_eb', 'secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics'], ARRAY['general_science'], ARRAY['computer_science', 'economics', 'civics', 'education', 'geography', 'islamic_history', 'islamic_studies', 'statistics', 'business_studies', 'english_literature', 'arabic', 'home_economics', 'physiology_hygiene', 'fine_arts', 'health_physical_education']),
  ('fbise', 'secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('fbise', 'secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics'], ARRAY['physics', 'chemistry', 'computer_science'], ARRAY[]::text[]),
  ('fbise', 'secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies', 'mathematics'], ARRAY['general_science'], ARRAY['computer_science', 'economics', 'civics', 'education', 'geography', 'islamic_history', 'islamic_studies', 'statistics', 'business_studies', 'english_literature', 'arabic', 'home_economics', 'physiology_hygiene', 'fine_arts', 'health_physical_education']),
  ('cambridge', 'secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies', 'mathematics'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('cambridge', 'secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies', 'mathematics'], ARRAY['physics', 'chemistry', 'computer_science'], ARRAY[]::text[]),
  ('cambridge', 'secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies', 'mathematics'], ARRAY[]::text[], ARRAY['economics', 'business_studies', 'accounting', 'commerce', 'sociology', 'english_literature', 'geography', 'history', 'statistics', 'additional_mathematics', 'environmental_management']),
  ('edexcel', 'secondary', 'bio', ARRAY['english', 'mathematics', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('edexcel', 'secondary', 'comp', ARRAY['english', 'mathematics', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'computer_science'], ARRAY[]::text[]),
  ('edexcel', 'secondary', 'arts', ARRAY['english', 'mathematics', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY[]::text[], ARRAY['economics', 'business_studies', 'accounting', 'commerce', 'english_literature', 'geography', 'history', 'information_technology', 'further_mathematics']),
  ('biek', 'higher_secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('biek', 'higher_secondary', 'eng', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'mathematics'], ARRAY[]::text[]),
  ('biek', 'higher_secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['computer_science', 'mathematics'], ARRAY['physics', 'statistics', 'economics']),
  ('biek', 'higher_secondary', 'commerce', ARRAY['english', 'urdu', 'islamiyat', 'pakistan_studies'], ARRAY['accounting', 'commerce', 'economics', 'business_mathematics', 'commercial_geography', 'statistics', 'banking'], ARRAY[]::text[]),
