  ('aku_eb', 'higher_secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('aku_eb', 'higher_secondary', 'eng', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'mathematics'], ARRAY[]::text[]),
  ('aku_eb', 'higher_secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['computer_science', 'mathematics'], ARRAY['physics', 'statistics', 'economics']),
  ('aku_eb', 'higher_secondary', 'commerce', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['accounting', 'commerce', 'economics'], ARRAY[]::text[]),
  ('aku_eb', 'higher_secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY[]::text[], ARRAY['economics', 'psychology', 'sociology', 'civics', 'education', 'islamic_history', 'islamic_studies', 'english_literature', 'urdu_elective', 'philosophy', 'statistics', 'geography', 'computer_science', 'fine_arts', 'health_physical_education']),
  ('fbise', 'higher_secondary', 'bio', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('fbise', 'higher_secondary', 'eng', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['physics', 'chemistry', 'mathematics'], ARRAY[]::text[]),
  ('fbise', 'higher_secondary', 'comp', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['computer_science', 'mathematics'], ARRAY['physics', 'statistics', 'economics']),
  ('fbise', 'higher_secondary', 'commerce', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY['accounting', 'commerce', 'economics'], ARRAY[]::text[]),
  ('fbise', 'higher_secondary', 'arts', ARRAY['english', 'urdu', 'islamiyat', 'translation_of_quran', 'pakistan_studies'], ARRAY[]::text[], ARRAY['economics', 'psychology', 'sociology', 'civics', 'education', 'islamic_history', 'islamic_studies', 'english_literature', 'urdu_elective', 'philosophy', 'statistics', 'geography', 'computer_science', 'fine_arts', 'health_physical_education']),
  ('cambridge', 'higher_secondary', 'bio', ARRAY[]::text[], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('cambridge', 'higher_secondary', 'eng', ARRAY[]::text[], ARRAY['mathematics', 'physics', 'chemistry'], ARRAY[]::text[]),
  ('cambridge', 'higher_secondary', 'comp', ARRAY[]::text[], ARRAY['mathematics', 'computer_science'], ARRAY['physics', 'further_mathematics', 'information_technology', 'economics']),
  ('cambridge', 'higher_secondary', 'commerce', ARRAY[]::text[], ARRAY['accounting', 'economics', 'business_studies'], ARRAY[]::text[]),
  ('cambridge', 'higher_secondary', 'arts', ARRAY[]::text[], ARRAY[]::text[], ARRAY['economics', 'accounting', 'business_studies', 'sociology', 'psychology', 'law', 'english_literature', 'english_general_paper', 'history', 'geography', 'urdu', 'mathematics']),
  ('edexcel', 'higher_secondary', 'bio', ARRAY[]::text[], ARRAY['physics', 'chemistry', 'biology'], ARRAY[]::text[]),
  ('edexcel', 'higher_secondary', 'eng', ARRAY[]::text[], ARRAY['mathematics', 'physics', 'chemistry'], ARRAY[]::text[]),
  ('edexcel', 'higher_secondary', 'comp', ARRAY[]::text[], ARRAY['mathematics', 'computer_science'], ARRAY['physics', 'further_mathematics', 'information_technology', 'economics']),
  ('edexcel', 'higher_secondary', 'commerce', ARRAY[]::text[], ARRAY['accounting', 'economics', 'business_studies'], ARRAY[]::text[]),
  ('edexcel', 'higher_secondary', 'arts', ARRAY[]::text[], ARRAY[]::text[], ARRAY['economics', 'accounting', 'business_studies', 'psychology', 'english_literature', 'history', 'geography', 'mathematics'])
) AS g(board, stage, group_code, compulsory, core, electives)
CROSS JOIN LATERAL (
  SELECT c, 'compulsory', 1, o FROM unnest(g.compulsory) WITH ORDINALITY AS t(c, o)
  UNION ALL SELECT c, 'core', 2, o FROM unnest(g.core) WITH ORDINALITY AS t(c, o)
  UNION ALL SELECT c, 'elective', 3, o FROM unnest(g.electives) WITH ORDINALITY AS t(c, o)
) AS s(code, kind, kind_order, ord);
-- END CURRICULUM SEED
