INSERT INTO public.curriculum_offerings (board, stage, label, note, sort_order) VALUES
  ('bsek', 'secondary', 'Matric (SSC)', 'In Sindh, students also take Sindhi: Urdu speakers take Asan Sindhi, Sindhi speakers take Urdu Salees.', 0),
  ('aku_eb', 'secondary', 'Matric (SSC)', 'In Sindh, students also take Sindhi: Urdu speakers take Asan Sindhi, Sindhi speakers take Urdu Salees.', 1),
  ('fbise', 'secondary', 'Matric (SSC)', NULL, 2),
  ('cambridge', 'secondary', 'O Level', 'Cambridge and Edexcel have no formal groups. These are our recommended subject combinations, matching the Pakistani groups that IBCC uses for equivalence.', 3),
  ('edexcel', 'secondary', 'International GCSE', 'Cambridge and Edexcel have no formal groups. These are our recommended subject combinations, matching the Pakistani groups that IBCC uses for equivalence. Urdu and Islamiyat are usually taken as Cambridge O Level papers alongside the IGCSEs.', 4),
  ('biek', 'higher_secondary', 'Intermediate (HSC)', 'Islamiyat is replaced by Civics for non-Muslim students. Sindhi-medium students may take a Sindhi paper in place of Urdu Paper II.', 5),
  ('aku_eb', 'higher_secondary', 'Intermediate (HSSC)', 'In Sindh, students also take Sindhi: Urdu speakers take Asan Sindhi, Sindhi speakers take Urdu Salees.', 6),
  ('fbise', 'higher_secondary', 'Intermediate (HSSC)', NULL, 7),
  ('cambridge', 'higher_secondary', 'A Level', 'Cambridge and Edexcel have no formal groups. These are our recommended subject combinations, matching the Pakistani groups that IBCC uses for equivalence.', 8),
  ('edexcel', 'higher_secondary', 'International A Level', 'Cambridge and Edexcel have no formal groups. These are our recommended subject combinations, matching the Pakistani groups that IBCC uses for equivalence.', 9)
